func (this *Geom_MiscellaneousTest) TestPredicatesReturnFalseForEmptyGeometries() {
	var p1 *Geom_Point = Geom_GeometryFactory_new().CreatePoint_Coordinate(nil)
	var p2 *Geom_Point = Geom_GeometryFactory_new().CreatePoint_Coordinate(Geom_Coordinate_new_double_double(float64(int32(5)), float64(int32(5))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Equals_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(true, p1.Disjoint_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Intersects_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Touches_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Crosses_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Within_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Contains_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p1.Overlaps_Geometry((*Geom_Geometry)(unsafe.Pointer(p2))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Equals_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(true, p2.Disjoint_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Intersects_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Touches_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Crosses_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Within_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Contains_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
	junit.TestCase_assertEquals_boolean_boolean(false, p2.Overlaps_Geometry((*Geom_Geometry)(unsafe.Pointer(p1))))
}
